package com.dylan.agent.capability.document.governance.provider;
import com.dylan.agent.adapter.api.operation.CapabilityOperationType;
import java.time.Instant;
public record DocumentProviderActivateRequest(String idempotencyKey,CapabilityOperationType operationType,String validationReportId,String expectedCurrentSnapshotDigest,Instant deadline){public DocumentProviderActivateRequest{validate(idempotencyKey,validationReportId,expectedCurrentSnapshotDigest,operationType,deadline);}@com.fasterxml.jackson.annotation.JsonAnySetter public void rejectUnknown(String name,Object value){throw new IllegalArgumentException("unknown management request field: "+name);}static void validate(String key,String report,String digest,Object type,Instant deadline){if(key==null||!key.matches("[A-Za-z0-9._:-]{8,128}")||report==null||!report.matches("[A-Za-z0-9._:-]{1,128}")||digest==null||!digest.matches("[0-9a-f]{64}")||type==null||deadline==null)throw new IllegalArgumentException("provider management request invalid");}}
